// The product backlog (docs/backlog.toml) is checked and its page generated by scripts/backlog.mjs, at each
// commit and in CI: these tests make sure the checker refuses what it must.
import { test } from "node:test";
import assert from "node:assert/strict";
import { parse } from "smol-toml";
import { backlogProblems } from "../scripts/backlog.mjs";

const MILESTONES = `
[[milestone]]
code = "v1"
name = "One"
goal = "g"
[[milestone]]
code = "v2"
name = "Two"
goal = "g"
`;
const item = (id, fields = "") => `
[[item]]
id = "${id}"
title = "t"
moscow = "must"
milestone = "v1"
module = "engine"
status = "to do"
added = 2026-10-24
tasks = ["[ ] a task"]
${fields}`;
const problems = (...items) => backlogProblems(parse(MILESTONES + items.join("")), new Set(["SIM-01"])).join("\n");

test("MAINT-05 a sound backlog passes", () => {
  assert.equal(problems(item("BL-01", 'features = ["SIM-01"]'), item("BL-02", 'depends_on = ["BL-01"]')), "");
});

test("MAINT-05 the checker refuses gaps, unknown values, a lying status and bad dependencies", () => {
  assert.match(problems(item("BL-02")), /identifier expected BL-01/);
  assert.match(problems(item("BL-01", 'features = ["NOPE-01"]')), /NOPE-01 not in the catalogue/);
  assert.match(problems(item("BL-01").replace('status = "to do"', 'status = "done"')), /tasks remain unticked/);
  assert.match(problems(item("BL-01").replace('"engine"', '"misc"')), /module "misc" outside/);
  const later = item("BL-01").replace('milestone = "v1"', 'milestone = "v2"');
  assert.match(problems(later, item("BL-02", 'depends_on = ["BL-01"]')), /planned later/);
  const could = item("BL-01").replace('"must"', '"could"');
  assert.match(problems(could, item("BL-02", 'depends_on = ["BL-01"]')), /a Must depending on BL-01/);
  assert.match(problems(item("BL-01", 'depends_on = ["BL-02"]'), item("BL-02", 'depends_on = ["BL-01"]')), /circular/);
});
